package io.metersphere.agent.controller;
import io.metersphere.agent.dto.*;import io.metersphere.agent.service.AgentPromptTemplateService;import io.metersphere.sdk.constants.PermissionConstants;import jakarta.annotation.Resource;import jakarta.validation.Valid;import org.apache.shiro.authz.annotation.RequiresPermissions;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping({"/ai/prompt-templates","/api/ai/prompt-templates"}) public class AgentPromptTemplateController {@Resource private AgentPromptTemplateService service;@GetMapping @RequiresPermissions(PermissionConstants.AI_MODEL_READ) public List<AgentPromptTemplateVersionDTO> list(@RequestParam String projectId,@RequestParam(required=false)String promptTemplateId){return service.list(projectId,promptTemplateId);}@PostMapping @RequiresPermissions(PermissionConstants.AI_MODEL_MANAGE) public AgentPromptTemplateVersionDTO create(@RequestBody @Valid AgentPromptTemplateVersionRequest r){return service.create(r);}@PostMapping("/{id}/publish") @RequiresPermissions(PermissionConstants.AI_MODEL_MANAGE) public AgentPromptTemplateVersionDTO publish(@PathVariable String id,@RequestParam String projectId){return service.publish(id,projectId);}@PostMapping("/{id}/preview") @RequiresPermissions(PermissionConstants.AI_MODEL_READ) public java.util.Map<String,Object> preview(@PathVariable String id,@RequestParam String projectId,@RequestBody(required=false) java.util.Map<String,Object> variables){return service.preview(id,projectId,variables);}@PostMapping("/{id}/rollback") @RequiresPermissions(PermissionConstants.AI_MODEL_MANAGE) public AgentPromptTemplateVersionDTO rollback(@PathVariable String id,@RequestParam String projectId){return service.rollback(id,projectId);}}
